const cfg=$('Runtime configuration').first().json||{};
if(!task.inputs.activity_base_url&&cfg.activity_base_url) task.inputs={...task.inputs, activity_base_url:cfg.activity_base_url};
return [{json:{...cfg, agent_task:task, case_id:task.case_id, task_id:task.task_id}}];

const opened=$json||{};
const runtime=(()=>{try{return $('Runtime configuration').first().json||{}}catch{return {}}})();
const result=opened.result&&typeof opened.result==='object'?opened.result:{};
if(typeof opened.ok!=='boolean'){
  return [{json:{
    task_id:result.task_id||opened.task_id||'',
    agent_id:"schedule_builder",
    status:'failed',
    message:"Сервис агента „Schedule Builder“ не отвечает по адресу из настроек среды. Проверьте, что он запущен, и перезапустите задачу.",
    data:{},
    artifacts:{},
    issues:[{code:'service_unreachable',url:String(runtime["schedule_service_url"]||'')}],
    assumptions:[],
    requests:[]
  }}];
}
return [{json:{
  task_id:result.task_id||opened.task_id||'',
  agent_id:"schedule_builder",
  status:result.status||'needs_input',
  message:result.message||opened.message||"Нет исходного SCHEDULE",
  data:result.data||{},
  artifacts:result.artifacts||{},
  issues:result.issues||[{type:"missing_schedule_source"}],
  assumptions:result.assumptions||[],
  requests:result.requests||[{question_id:"Q-apply",question:"К задаче не приложен исходный файл schedule. Приложите прогнозный .inc, который нужно изменить.",options:[],accepts:{free_text:true,files:["xlsx", ".inc"]}}]
}}];

const RAG_TARGET_BASE="schedule_mvp";
const RAG_ACCESS_SCOPE="petroleum-engineering";
const RAG_KNOWLEDGE_TYPES=["keyword_instruction", "worked_example"];
const RAG_TOP_K=10;
const RAG_TOPICS=[];
const opened=$json||{};
const task=$('Normalize schedule task').first().json.agent_task||{};
const objective=String(opened.objective||task.objective||'');
const handoff=String(opened.handoff_message||task.handoff_message||'');
const blob=[objective,handoff].join('\n');
const low=blob.toLowerCase();
// Retrieval filters from inspect / expected_output (spec JS). Task text is query only.
const keyword_families=[];
const topics=RAG_TOPICS.slice();
const task_patterns=[];
const ALLOWED_KEYWORDS=["DATES", "INCLUDE", "GRUPTREE", "WELSPECS", "WELLTRACK", "COMPDATMD", "WCONHIST", "WCONPROD", "WCONINJE", "GCONPROD", "GCONINJE", "GUIDERAT", "GSATPROD", "GSATINJE", "WELLSTRE", "WINJGAS", "GINJGAS", "BRANPROP", "NODEPROP", "GNETDP", "NETBALAN", "FRACTURE_TEMPLATE", "FRACTURE_SPECS", "FRACTURE_STAGE", "WECON", "WTEST", "WELTARG", "WNETDP", "WPIMULT", "WDFAC", "WEFAC", "WELOPEN", "WELDRAW", "WLIST", "WFRACP", "WFRACPL", "VFPPROD", "WVFPDP", "ACTIONX", "DELAYACT", "ENDACTIO", "UDQ", "UDT", "APPLYSCRIPT"];

const allowed=new Set(ALLOWED_KEYWORDS);
const inspect=opened.inspect&&typeof opened.inspect==='object'?opened.inspect:{};
const expected=opened.expected_output&&typeof opened.expected_output==='object'?opened.expected_output:((task.inputs&&task.inputs.expected_output&&typeof task.inputs.expected_output==='object')?task.inputs.expected_output:{});
const ranked=[];
const seenKw=new Set();
function addKw(raw){
  const k=String(raw||'').trim().toUpperCase();
  if(!k||!allowed.has(k)||seenKw.has(k)) return;
  seenKw.add(k);
  ranked.push(k);
}
function walkDataset(v){
  if(!v) return;
  if(typeof v==='string'){ addKw(v); return; }
  if(Array.isArray(v)){ v.forEach(walkDataset); return; }
  if(typeof v==='object'){
    addKw(v.name);
    if(Array.isArray(v.keywords)) v.keywords.forEach(addKw);
    if(Array.isArray(v.fields)) v.fields.forEach((f)=>{ if(f&&typeof f==='object') addKw(f.name); else addKw(f); });
  }
}
walkDataset(expected.datasets);
walkDataset(opened.datasets);
for(const k of (Array.isArray(inspect.keywords_present)?inspect.keywords_present:[])) addKw(k);
keyword_families.push(...ranked.slice(0,6));
const query=blob.trim().replace(/\b[\w.-]+\.(xlsx|xls|xlsm|inc|dev|txt|csv)\b/gi,' ').replace(/\s+/g,' ').trim().slice(0,800)||"schedule_mvp instruction";
const retrieval_selector={target_base:RAG_TARGET_BASE,knowledge_types:RAG_KNOWLEDGE_TYPES};
const schedule_retrieval_request={
  query,
  filters:{target_base:RAG_TARGET_BASE,access_scope:RAG_ACCESS_SCOPE,knowledge_types:RAG_KNOWLEDGE_TYPES,keyword_families:[...new Set(keyword_families)].slice(0,6),topics:[...new Set(topics)],task_patterns:[...new Set(task_patterns)]},
  top_k:RAG_TOP_K
};
// The LLM decides which tool fits: task text + what open_session found + what the engineer already answered.
const engineerAnswers=Array.isArray(opened.engineer_answers)?opened.engineer_answers:[];
const reworkReason=String(opened.rework_reason||(task.inputs&&task.inputs.rework_reason)||'').trim();
const planner_input=JSON.stringify({
  objective,
  handoff_message:handoff,
  inspect:opened.inspect||{},
  fact_count:opened.fact_count||0,
  facts_preview:opened.facts_preview||[],
  dataset_count:opened.dataset_count||0,
  datasets:opened.datasets||[],
  engineer_answers:engineerAnswers,
  ...(reworkReason?{rework_reason:reworkReason}:{}),
  ...(opened.expected_output&&typeof opened.expected_output==='object'&&Object.keys(opened.expected_output).length?{expected_output:opened.expected_output}:{})
});
return [{json:{...opened,session_id:opened.session_id,agent_input:planner_input,planner_input,schedule_retrieval_request,retrieval_selector}}];

function unwrapRetrieval(raw){
  const obj=v=>v&&typeof v==='object'&&!Array.isArray(v);
  const src=obj(raw)?raw:{};
  if(obj(src.schedule_retrieval_result)) return src.schedule_retrieval_result;
  if(obj(src.body)&&obj(src.body.schedule_retrieval_result)) return src.body.schedule_retrieval_result;
  if(String(src.contract||'')==='schedule_retrieval_result') return src;
  if(src.error||Number(src.statusCode)>=400) return {status:'failed',findings:[{code:'RETRIEVAL_CALL_FAILED'}],results:[]};
  return src;
}
function retrievalOutage(result, raw){
  if(Boolean(raw&&raw.error)||Number(raw&&raw.statusCode)>=400) return 'failed';
  const st=String((result&&result.status)||'').toLowerCase();
  if(st==='failed'||st==='error') return 'failed';
  if(st==='needs_input') return 'needs_input';
  if(st==='abstain') return 'abstain';
  if(st==='unavailable') return 'unavailable';
  return '';
}
function compactRetrievalCards(result, selector, limit, textLimit, preferFull){
  const rows=Array.isArray(result.results)?result.results:[];
  const wantedBase=String(selector.target_base||'');
  const wantedTypes=new Set((selector.knowledge_types||[]).map(v=>String(v).toLowerCase()));
  const cap=Number(limit)||6;
  const cut=Number(textLimit)||700;
  const minText=50;
  const relKeep=0.45;
  const scored=[];
  for(const r of rows){
    if(!r||typeof r!=='object') continue;
    const body=r.body&&typeof r.body==='object'?r.body:{};
    const base=String(r.target_base||body.target_base||(result.filters&&result.filters.target_base)||'');
    const kt=String(r.knowledge_type||body.knowledge_type||'').toLowerCase();
    if(wantedBase&&base&&base!==wantedBase) continue;
    if(wantedTypes.size&&kt&&!wantedTypes.has(kt)) continue;
    const summary=String(body.summary||r.summary||'').trim();
    const full=String(body.text||body.instruction||r.text||'').trim();
    const text=preferFull?(full||summary):(summary||full);
    if(text.length<minText) continue;
    const score=r.rrf_score!=null?Number(r.rrf_score):(body.rrf_score!=null?Number(body.rrf_score):null);
    if(Number.isFinite(score)&&score<=0) continue;
    const topics=Array.isArray(r.topics)?r.topics:(Array.isArray(body.topics)?body.topics:[]);
    scored.push({
      knowledge_id:String(r.knowledge_id||body.knowledge_id||''),
      title:String(r.title||body.title||'').slice(0,160),
      knowledge_type:kt||null,
      text:text.slice(0,cut),
      revision:(r.revision!=null&&r.revision!=='')?r.revision:((body.revision!=null&&body.revision!=='')?body.revision:null),
      rrf_score:Number.isFinite(score)?score:null,
      branches:Array.isArray(r.branches)?r.branches.slice(0,6).map(b=>String(b)):(Array.isArray(body.branches)?body.branches.slice(0,6).map(b=>String(b)):[]),
      topics:topics.slice(0,12).map(t=>String(t||'').trim()).filter(Boolean),
      _score:Number.isFinite(score)?score:null
    });
  }
  const finite=scored.map(c=>c._score).filter(s=>s!=null);
  const best=finite.length?Math.max.apply(null,finite):0;
  const floor=best>0?best*relKeep:0;
  const want=new Set((Array.isArray(selector.topics)?selector.topics:[]).map(t=>String(t||'').toLowerCase()).filter(Boolean));
  const orch=String(selector.target_base||'')==='orchestrator_routing';
  const kept=scored.filter(c=>{
    if(c._score==null||floor<=0) return true;
    const cardTopics=(Array.isArray(c.topics)?c.topics:[]).map(t=>String(t||'').toLowerCase());
    if(want.size&&cardTopics.some(t=>want.has(t))) return true;
    if(orch&&want.size) return false;
    const n=Array.isArray(c.branches)?c.branches.length:0;
    if(n<2) return true;
    return c._score>=floor;
  });
  kept.sort((a,b)=>{
    if(a._score==null&&b._score==null) return 0;
    if(a._score==null) return 1;
    if(b._score==null) return -1;
    return b._score-a._score;
  });
  return kept.slice(0,cap).map(c=>({knowledge_id:c.knowledge_id,title:c.title,knowledge_type:c.knowledge_type,text:c.text,revision:c.revision,rrf_score:c.rrf_score,branches:c.branches,topics:c.topics}));
}
const prev=$("Prepare AI Agent input").first().json||{};
const raw=$json||{};
const obj=v=>v&&typeof v==='object'&&!Array.isArray(v);
const result=unwrapRetrieval(raw);
const fallbackSelector={"target_base": "schedule_mvp", "knowledge_types": ["keyword_instruction", "worked_example"]};
const fromPrev=prev.retrieval_selector;
const req=obj(prev.schedule_retrieval_request)?prev.schedule_retrieval_request:{};
const wantTopics=Array.isArray(req.filters&&req.filters.topics)?req.filters.topics:[];
const selector=(fromPrev&&fromPrev.target_base)?{target_base:String(fromPrev.target_base),knowledge_types:Array.isArray(fromPrev.knowledge_types)&&fromPrev.knowledge_types.length?fromPrev.knowledge_types:fallbackSelector.knowledge_types,topics:wantTopics}:Object.assign({},fallbackSelector,{topics:wantTopics});
const outage=retrievalOutage(result,raw);
const cards=(outage==='failed'||outage==='needs_input')?[]:compactRetrievalCards(result,selector,6,800);
const rag={contract:'mas_rag_evidence',contract_version:'1.0',target_base:selector.target_base,knowledge_types:selector.knowledge_types,status:outage||(cards.length?'ready':'empty'),phase:"initial",cards,findings:(Array.isArray(result.findings)?result.findings:[]).slice(0,6).map(f=>f&&f.code).filter(Boolean)};
const note=rag.status==='ready'?"Карточки — срез schedule_mvp (keyword_instruction / worked_example), не excel_protocol и не orchestrator_routing. Стартовый срез — краткие summary (when-to-use). Перед apply_dataset — retrieve_knowledge (полный текст), затем get_keyword.details. Не schema_catalogue из RAG.":"Срез schedule_mvp пуст или недоступен — работай инструментами. Не спрашивай HITL про RAG и не ходи в другие target_base.";
const planner=`${prev.planner_input||prev.agent_input||''}\n\nRetrieved knowledge (target_base=${selector.target_base}):\n${JSON.stringify(rag,null,2)}\n\n${note}\n`;
const logCards=(Array.isArray(cards)?cards:[]).map(c=>({knowledge_id:String((c&&c.knowledge_id)||''),revision:(c&&c.revision)!=null?c.revision:null,rrf_score:Number.isFinite(Number(c&&c.rrf_score))?Number(c.rrf_score):null,branches:Array.isArray(c&&c.branches)?c.branches.slice(0,6):[]}));
const logFindings=(Array.isArray(result.findings)?result.findings:[]).slice(0,8).map(f=>{if(obj(f)&&f.code)return{code:String(f.code)};const code=String(f||'').trim();return code?{code}:null}).filter(Boolean);
const activity={activity_kind:'trace.rag',status_message:`База знаний: ${rag.status} · ${logCards.length} карточек`,activity_payload:{caller:"schedule_builder",query:String(req.query||result.query||'').slice(0,800),filters:obj(req.filters)?req.filters:{},status:rag.status,phase:rag.phase,findings:logFindings,cards:logCards}};
return [{json:{...prev,rag,planner_input:planner,agent_input:planner,...activity}}];

function fromNode(name){
  try{
    const n=$(name);
    if(n&&n.item&&n.item.json) return n.item.json;
    if(n&&typeof n.last==='function'){const x=n.last(); if(x&&x.json) return x.json;}
    if(n&&typeof n.first==='function'){const x=n.first(); if(x&&x.json) return x.json;}
  }catch(e){}
  return {};
}
function obj(v){return v&&typeof v==='object'&&!Array.isArray(v);}
function stripThink(text){return String(text||'').replace(/<think>[\s\S]*?<\/think>/gi,' ').replace(/\s+/g,' ').trim();}
function clip(text,n){const s=String(text||''); return s.length<=n?s:s.slice(0,n-1)+'…';}
function parseArgs(raw){
  if(obj(raw)) return raw;
  const s=String(raw||'').trim();
  if(!s) return {};
  try{const p=JSON.parse(s); return obj(p)?p:{};}catch(e){return {};}
}
function looksMachine(text){
  const s=String(text||'');
  if(!s.trim()) return false;
  return /[a-z]+_[a-z_]+|[a-z_]+=[a-z0-9]+|[{}\[\]]|\w\|\w/.test(s)||/\bbaseline\b/i.test(s)||!/[А-Яа-яЁё]{3,}/.test(s);
}
function loopRouteForPending(pending, over){
  const list=Array.isArray(pending)?pending:[];
  if(list.length){
    const name=String((list[0]&&list[0].name)||'');
    return name==='retrieve_knowledge'?'retrieve':'tool';
  }
  return over?'done':'chat';
}
function toolTransportCode(http){
  if(!http||typeof http.ok==='boolean') return '';
  const err=obj(http.error)?http.error:(typeof http.error==='string'?{message:http.error}:null);
  const status=Number(http.statusCode||http.status||(err&&err.status)||0);
  const blob=String((err&&(err.httpCode||err.code||err.message||err.description))||'').toLowerCase();
  if(/econnrefused|enotfound|etimedout|econnreset|ehostunreach|socket hang|connection|offline|unreachable/.test(blob)) return 'service_unreachable';
  if(status>=500) return 'service_unreachable';
  if(err&&(status===0||!status)&&!http.choices) return 'service_unreachable';
  if(err||status>=400) return 'tool_http_failed';
  return '';
}
function parseChatExtra(cfg){
  const raw=cfg&&cfg.chat_extra_params;
  let parsed={};
  if(raw&&typeof raw==='object'&&!Array.isArray(raw)) parsed=raw;
  else {
    const s=String(raw||'').trim();
    if(s){
      try{const p=JSON.parse(s); if(p&&typeof p==='object'&&!Array.isArray(p)) parsed=p;}catch(e){parsed={};}
    }
  }
  const out={...parsed};
  delete out.messages;
  delete out.tools;
  delete out.tool_choice;
  return out;
}
function previewChatMessages(msgs, fromIdx){
  const CONTENT=600;
  const KEEP=10;
  const list=Array.isArray(msgs)?msgs:[];
  const slim=(m)=>{
    const raw=m&&typeof m==='object'&&!Array.isArray(m)?m:{};
    const c=raw.content;
    let text='';
    if(typeof c==='string') text=c;
    else if(c==null) text='';
    else { try{text=JSON.stringify(c);}catch(e){text=String(c);} }
    if(text.length>CONTENT) text=text.slice(0,CONTENT-1)+'…';
    const out={role:String(raw.role||''),content:text};
    if(raw.tool_call_id) out.tool_call_id=String(raw.tool_call_id);
    if(Array.isArray(raw.tool_calls)&&raw.tool_calls.length) out.tool_calls=raw.tool_calls.length;
    return out;
  };
  const all=list.map(slim);
  const start=Math.max(0,Number(fromIdx)||0);
  let picked=start>0?all.slice(start):all.slice();
  let omitted=0;
  if(start>0&&all[0]&&all[0].role==='system'){
    omitted=Math.max(0,start-1);
    picked=[all[0],...(omitted?[{role:'omitted',count:omitted}]:[]),...picked];
  }
  if(picked.length>KEEP){
    omitted += picked.length-KEEP;
    picked=[picked[0],{role:'omitted',count:omitted},...picked.slice(-(KEEP-2))];
  }
  const preview={messages:picked};
  if(omitted) preview.omitted=omitted;
  return preview;
}
const SYSTEM="Ты — инженер-решатель агента Schedule Builder: читаешь задачу инженера, выбираешь инструмент и вызываешь его со структурированными аргументами. Текст SCHEDULE (.INC) пишут инструменты, не ты.\n\nИсходный .INC тебе не показывают — он лежит в сессии FastAPI. session_id привязан workflow: никогда не передавай session_id и обёртку args/input.\n\nКакой инструмент когда:\n- Задача про НОВЫЕ ДАТЫ ВВОДА скважин (Excel «скважина — дата», fact_count > 0) → apply_commissioning. Факты, решение по скважинам вне Excel и параметры новых скважин уже в сессии — аргументов не нужно. Другие apply_* для такой задачи не вызывай.\n- Задача про ГРУППЫ (поместить скважины в группу, групповой контроль GCONPROD) → inspect_schedule (имена скважин, дерево GRUPTREE), затем apply_group_rebind с полным spec: wells, parent_group, parent_of_parent, control (ORAT/WRAT/GRAT/LRAT/RESV), gas_rate числом в м3/сут («200 тыс. м3 газа в сут.» → 200000). Родителя новой группы бери из дерева исходного файла (корень — FIELD или как в inspect), если инженер не сказал иначе.\n- В сессии есть именованные наборы (dataset_count > 0, не пары «скважина — дата ввода»): inspect_dataset по имени → retrieve_knowledge (query — смысл набора, keywords — имя keyword) → get_keyword → apply_dataset с field_map. retrieve_knowledge не пропускай: стартовый срез — краткие summary чужих keyword, полный when-to-use только из retrieve. Нет поля даты в наборе — не спрашивай инженера про дату; apply_dataset без date_field обновляет существующие записи скважины. inspect_schedule и search_keywords не вызывай, если retrieve + get_keyword уже дали keyword и поля. Не выдумывай keyword и не подставляй пустые значения. apply_commissioning сюда не подходит.\n- Точечные правки режимов/keywords без набора: если keyword нет в текущих карточках — retrieve_knowledge, затем get_keyword (details.parameters) → apply_operations или render_ir. search_keywords — только если retrieve пуст.\n- inspect_well / analyze_forecast_controls / list_records — чтобы посмотреть скважину перед правкой. Не вызывай их «на всякий случай» и не больше трёх раз подряд.\n- build_schedule — только если apply уже менял сессию; validate_result — проверки emit.\n- ask_engineer — единственный способ спросить инженера. Только когда данных нет ни в задаче, ни в исходном файле, ни в ответах инженера (engineer_answers), ни в наборе. Не спрашивай дату шага, если в наборе нет поля даты. Один вопрос обычной русской фразой: что нужно и зачем; варианты (options) — как их называет инженер: имена групп из исходного файла, «оставить»/«убрать». Никаких имён полей, JSON, enum, кодов. Инженер отвечает фактами, таблицами и файлами — не строками .INC.\n\nОтветы инструментов:\n- ok:false, code:spec_incomplete — это тебе, не инженеру: заполни missing из текста задачи, inspect_schedule и inspect_dataset (where_to_find подсказывает откуда) и вызови инструмент снова. Спрашивай инженера, только если данных действительно нет.\n- ok:false, code:dataset_values_missing — в наборе пустые обязательные поля: спроси инженера через ask_engineer, не подставляй значения сам.\n- ok:false, code:question_not_human — переформулируй вопрос прозой и вызови ask_engineer снова.\n- ok:false, code:well_not_in_schedule / operations_required / unknown_dataset / unknown_keyword — ошибка твоего вызова; исправь аргументы.\n- ok:false, code:knowledge_required — сначала retrieve_knowledge (query и keywords набора), затем get_keyword, затем apply_dataset.\n- ok:false, code:result_already_stored — результат этого запуска уже зафиксирован (apply или вопрос инженеру). Больше инструменты не вызывай, заверши ответ.\n- status completed или needs_input от apply_* / ask_engineer — результат зафиксирован. STOP: не вызывай build и другие apply.\n\nИнварианты:\n- Не придумывай скважины, даты, группы, дебиты. Имена скважин — только из inspect_schedule.\n- Если комментарий WCONPROD содержит «факт»/«fact», запись фактическая: её нельзя удалять, переносить или считать прогнозным якорем ввода. Якорь commissioning — первый нефактический WCONPROD; следующие WCONPROD — прогнозные режимы, они сохраняются.\n- Один параметр после существующего контроля — WELTARG, не переписывание WCONPROD. Не путай WECON (экономика), WTEST (переоткрытие), WELOPEN (статус), WEFAC (uptime), WPIMULT (CF), GCONPROD (группа).\n- Имена полей — из get_keyword.details (WELL, DATE, CHILD). WCONPROD variant = CONTROL в нижнем регистре (orat, wrat, grat, lrat, bhp, thp, resv, grup); если variant не указан — положи CONTROL в fields.\n- apply_operations принимает JSON-массив [{keyword, operation, fields}], не объект с ключами \"0\",\"1\".\n- Если analyze_forecast_controls вернул needs_input по границе history/forecast — не применяй операцию, спроси инженера.\n- rework_reason в задаче — замечание оркестратора к прошлому результату: устрани именно его.\n- Retrieved knowledge — срез schedule_mvp (keyword_instruction / worked_example): стартовый Attach — краткие summary. Перед apply_dataset всегда retrieve_knowledge, затем get_keyword. Нет даты в наборе — не спрашивай HITL про дату шага, date_field не передавай. Перед первым apply_operations / render_ir по keyword, которого нет в карточках, — тоже retrieve_knowledge. apply_commissioning для дат ввода — без retrieve. Расклад полей — get_keyword.details. Пустой или unavailable срез — работай инструментами, не спрашивай про базу знаний.\n\nЗаверши одним коротким фактическим предложением по-русски о том, что сделано или чего не хватило.\n";
